package pe.cruzroja.convocatorias.justifications.domain; import java.time.*; import java.util.List; public class PenaltyPolicy {public static final int ABSENCES=3,WINDOW_DAYS=90,SUSPENSION_DAYS=30; public boolean shouldSuspend(List<LocalDateTime> unjustified,LocalDateTime now){return unjustified.stream().filter(d->!d.isBefore(now.minusDays(WINDOW_DAYS))).count()>=ABSENCES;} public LocalDateTime suspensionEnd(LocalDateTime from){return from.plusDays(SUSPENSION_DAYS);} }
